package com.learn.hub.data;

import java.util.List;

import org.springframework.dao.DeadlockLoserDataAccessException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.retry.annotation.Backoff;
import org.springframework.retry.annotation.Retryable;
import org.springframework.stereotype.Repository;

/** 死锁由数据库自动回滚一方，应用只需有限重试，不能无限循环。 */
@Repository
public class SeatRepository {

    private final JdbcTemplate jdbc;

    public SeatRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    @Retryable(retryFor = DeadlockLoserDataAccessException.class,
               maxAttempts = 3,
               backoff = @Backoff(delay = 50, multiplier = 2))
    public boolean reserve(long courseId) {
        int updated = jdbc.update("""
                UPDATE course_seat
                   SET stock = stock - 1, version = version + 1
                 WHERE course_id = ? AND stock > 0
                """, courseId);
        return updated == 1;
    }

    /** 多行一起锁定时按主键升序，统一顺序才能消除循环等待。 */
    public List<Long> lockOrder(List<Long> ids) {
        return ids.stream().sorted().toList();
    }
}
